import 'package:flutter/foundation.dart';
import 'package:flutter/services.dart';

/// Adds native libraries (CocoaPods, Gradle, vendored C++) to the license
/// page. The assets are generated by scripts/native_licenses.py.
void registerNativeLicenses() {
  LicenseRegistry.addLicense(() async* {
    final files = [
      'assets/licenses/shared.md',
      if (defaultTargetPlatform == TargetPlatform.iOS)
        'assets/licenses/ios.md'
      else if (defaultTargetPlatform == TargetPlatform.android)
        'assets/licenses/android.md',
    ];
    for (final file in files) {
      final text = await rootBundle.loadString(file);
      for (final section in text.split(RegExp(r'^## ', multiLine: true))) {
        final newline = section.indexOf('\n');
        if (newline <= 0) continue;
        yield LicenseEntryWithLineBreaks([
          section.substring(0, newline).trim(),
        ], section.substring(newline).trim());
      }
    }
  });
}
